namespace CheckoutPricing.Domain;

public static class LoyaltyDiscount
{
    private const int MaxRatePoints = 10;
    private const int SilverBandFloorCents = 5_000;
    private const int TopBandFloorCents = 20_000;

    public static int DiscountCentsFor(int subtotalCents, LoyaltyTier tier)
    {
        var points = Math.Min(BaseRatePoints(tier) + BandBonusPoints(subtotalCents), MaxRatePoints);
        return (int)((long)subtotalCents * points / 100);
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null),
    };

    private static int BandBonusPoints(int subtotalCents) =>
        subtotalCents >= TopBandFloorCents ? 3 : subtotalCents >= SilverBandFloorCents ? 1 : 0;
}
